import React, { useState, useEffect } from 'react';
import axios from 'axios';

const BACKEND_URL = 'http://localhost:5000';

const Dashboard = () => {
  const token = localStorage.getItem('token');
  const [skills, setSkills] = useState([]);
  const [mode, setMode] = useState('list');
  const [currentSkillName, setCurrentSkillName] = useState('');
  const [relatedSubSkills, setRelatedSubSkills] = useState([]);
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [editingSkillId, setEditingSkillId] = useState(null);
  const [aiSuggestions, setAiSuggestions] = useState({});
  const [loadingSkillId, setLoadingSkillId] = useState(null);

  useEffect(() => {
    fetchSkills();
  }, []);

  const fetchSkills = async () => {
    try {
      const res = await axios.get(`${BACKEND_URL}/api/skills`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSkills(res.data);
    } catch (err) {
      console.error('Failed to fetch skills:', err);
    }
  };

  const handleAddSkillName = () => {
    if (!currentSkillName.trim()) {
      alert('Please enter a skill name');
      return;
    }
    fetchRelatedSubSkills(currentSkillName.trim());
  };

  const fetchRelatedSubSkills = async (skillName) => {
    try {
      const res = await axios.post(
        `${BACKEND_URL}/api/openai/getRelatedSkills`,
        { skillName },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      const related = res.data.relatedSkills || [];
      if (related.length === 0) {
        alert('No related skills found from AI.');
        return;
      }
      const initialSubs = related.map(name => ({ name, level: 5 }));
      setRelatedSubSkills(initialSubs);
      setAiSuggestion('');
      setMode('questionnaire');
      setEditingSkillId(null);
    } catch (error) {
      console.error('Error fetching sub-skills:', error);
      alert('Could not fetch related sub-skills.');
    }
  };

  const handleSubSkillLevelChange = (index, newLevel) => {
    const updated = [...relatedSubSkills];
    updated[index].level = Number(newLevel);
    setRelatedSubSkills(updated);
  };

  const handleQuestionnaireSubmit = async () => {
    try {
      const payload = {
        skillName: currentSkillName,
        subSkills: relatedSubSkills
      };
      const res = await axios.post(`${BACKEND_URL}/api/openai/analyzeSkillLevels`, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });

      const { suggestion, overallProgress } = res.data;
      setAiSuggestion(suggestion || 'No suggestions available.');

      if (editingSkillId) {
        await axios.put(
          `${BACKEND_URL}/api/skills/${editingSkillId}`,
          { name: currentSkillName, progress: overallProgress, subSkills: relatedSubSkills },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      } else {
        await axios.post(
          `${BACKEND_URL}/api/skills`,
          { name: currentSkillName, progress: overallProgress, subSkills: relatedSubSkills },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      }

      setMode('list');
      setCurrentSkillName('');
      setRelatedSubSkills([]);
      setEditingSkillId(null);
      fetchSkills();
    } catch (error) {
      console.error('Error submitting skill levels:', error);
      alert('Submission failed.');
    }
  };

  const handleEditSkill = async (skill) => {
    setCurrentSkillName(skill.name);
    setEditingSkillId(skill.id);
    setAiSuggestion('');
    const subSkills = skill.subSkills || [];

    if (subSkills.length > 0) {
      setRelatedSubSkills(subSkills);
      setMode('questionnaire');
    } else {
      try {
        const res = await axios.post(
          `${BACKEND_URL}/api/openai/getRelatedSkills`,
          { skillName: skill.name },
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const related = res.data.relatedSkills || [];
        const initialSubs = related.map(name => ({ name, level: 5 }));
        setRelatedSubSkills(initialSubs);
        setMode('questionnaire');
      } catch {
        alert('Could not fetch related sub-skills.');
      }
    }
  };

  const handleDeleteSkill = async (skillId) => {
    if (!window.confirm('Are you sure you want to delete this skill?')) return;
    try {
      await axios.delete(`${BACKEND_URL}/api/skills/${skillId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchSkills();
    } catch (error) {
      console.error('Delete failed:', error);
      alert('Could not delete skill.');
    }
  };

  const handleAiSuggestionSkill = async (skill) => {
    setLoadingSkillId(skill.id);
    setAiSuggestions((prev) => ({ ...prev, [skill.id]: null }));
    try {
      const payload = {
        skillName: skill.name,
        subSkills: skill.subSkills?.length
          ? skill.subSkills
          : [{ name: `${skill.name} Basics`, level: 5 }]
      };

      const res = await axios.post(`${BACKEND_URL}/api/openai/analyzeSkillLevels`, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });

      const suggestion = res.data?.suggestion || 'No suggestions available.';
      setAiSuggestions((prev) => ({ ...prev, [skill.id]: suggestion }));
    } catch (error) {
      console.error('AI suggestion error:', error);
      setAiSuggestions((prev) => ({ ...prev, [skill.id]: 'Failed to get suggestion.' }));
    } finally {
      setLoadingSkillId(null);
    }
  };

  // Views
  if (mode === 'addSkillName') {
    return (
      <div className="container" style={{ maxWidth: 600, marginTop: 40 }}>
        <h2>Add New Skill</h2>
        <input
          type="text"
          className="form-control mb-3"
          placeholder="Enter skill name"
          value={currentSkillName}
          onChange={e => setCurrentSkillName(e.target.value)}
        />
        <button className="btn btn-primary" onClick={handleAddSkillName}>Continue</button>
        <button className="btn btn-secondary ms-2" onClick={() => setMode('list')}>Back to Skills</button>
      </div>
    );
  }

  if (mode === 'questionnaire') {
    return (
      <div className="container" style={{ maxWidth: 600, marginTop: 40 }}>
        <h2>Rate Sub-Skills for "{currentSkillName}"</h2>
        {relatedSubSkills.map((sub, idx) => (
          <div key={sub.name} className="mb-3">
            <label>{sub.name}: {sub.level}</label>
            <input
              type="range"
              min="1"
              max="10"
              value={sub.level}
              onChange={e => handleSubSkillLevelChange(idx, e.target.value)}
              className="form-range"
            />
          </div>
        ))}

        <button className="btn btn-success" onClick={handleQuestionnaireSubmit}>Submit & Get Suggestions</button>
        <button className="btn btn-secondary ms-2" onClick={() => setMode('list')}>Cancel</button>

        {aiSuggestion && (
          <div className="alert alert-info mt-4" style={{ whiteSpace: 'pre-wrap' }}>
            <strong>AI Suggestions:</strong><br />
            {aiSuggestion}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="container" style={{ maxWidth: 800, marginTop: 40 }}>
      <h2>Your Skills</h2>
      <button className="btn btn-link mb-3" onClick={() => setMode('addSkillName')}>+ Add New Skill</button>
      {skills.length === 0 && <p>No skills added yet.</p>}

      <ul className="list-group">
        {skills.map(skill => (
          <li key={skill.id} className="list-group-item d-flex flex-column align-items-start">
            <div className="d-flex justify-content-between w-100">
              <div>
                <strong>{skill.name}</strong>
                <div className="progress mt-1" style={{ height: '20px', width: '250px' }}>
                  <div
                    className="progress-bar"
                    role="progressbar"
                    style={{ width: `${skill.progress}%` }}
                    aria-valuenow={skill.progress}
                    aria-valuemin="0"
                    aria-valuemax="100"
                  >
                    {skill.progress}%
                  </div>
                </div>
              </div>
              <div className="btn-group">
                <button className="btn btn-sm btn-outline-primary" onClick={() => handleEditSkill(skill)}>Edit</button>
                <button className="btn btn-sm btn-outline-danger" onClick={() => handleDeleteSkill(skill.id)}>Delete</button>
                <button
                  className="btn btn-sm btn-outline-info"
                  onClick={() => handleAiSuggestionSkill(skill)}
                  disabled={loadingSkillId === skill.id}
                >
                  {loadingSkillId === skill.id ? 'Loading...' : 'AI Suggestion'}
                </button>
              </div>
            </div>
            {aiSuggestions[skill.id] && (
              <div className="alert alert-secondary mt-2" style={{ whiteSpace: 'pre-wrap' }}>
                <strong>Suggestion:</strong><br />
                {aiSuggestions[skill.id]}
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Dashboard;
